    accountsB2Desc: 'ཁྱོད་ཀྱིས་ཁ་བྱང་ཞིག་དང་ཡང་ན་ཁ་པར་ཨང་གྲངས་ཞིག་བཀོད་ནས་ཡོང་བའི་ཡིག་རྟགས་དེ་ངོས་ལེན་བྱེད་དགོས ། ཐབས་ལམ་གཉིས་ཀ་འདྲ་མཚུངས་ཀྱིས་DeHub གི་རྒྱུད་འཛིན་རྩིས་དེ་གསར་པའི་སྒྲོམ་ལ་སྤོར་བ་རེད །',
