    uploadTokenGated: 'གསང་བའི་འཆིང་ཡིག་གི་ལྟ་བཤལ་པ་གང་རུང་གི་རྒྱབ་ཏུ་སྦྲེལ་ཡོད་པའི་අන්තර්ගතདེར་སྤོར་བའམ ། ཡར་སྤོར་བའམ །',
    uploadPPV: 'pay-per-view ཡང་ན་འཚོ་བཞིན་པའི་རྒྱུགས་ཆུའི་ཆེད་དུ་གསང་བའི་གླ་ཆ་གང་འདྲ་ཞིག་ལེན་དགོས །',
    uploadNFT: 'nFT ཞིག་ཏུ་བཀོད་ནས་དེའི་ནང་ཚེ་རིང་གི་རྒྱལ་སྲས་རྣམས་ཡོད་པའི་བརྙན་འཕྲིན་ཞིག་ཡོད ། ཕྱིར་འདོན་བྱ་རྒྱུ་དེ་གདམ་ཁ་ཅན་ཞིག་རེད ། ཕྱིར་འདོན་བྱ་རྒྱུ་དེ་འཕྲལ་དུ་ཕྱིར་འདོན་བྱ་རྒྱུ་རེད ། ཕྱིར་འདོན་བྱ་རྒྱུ་དེ་ཡང་མ་ཡིན །',
    uploadEarn: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་10 ལས་ཉུང་བ ། ཐོན་རིམ་5.7.1 ནང་དུ་ཚོད་ལྟ་བྱས་ཟིན ། ཟླ 6 སྔོན་ལ་གསར་བཅོས་བྱས །',
    uploadSubscribers: 'ཤོག་ངོས་འདི་ཡི་བཟོ་བཅོས་མཐའ་མ་འདི་ཡི་བཟོ་བཅོས་མཐའ་མ་ཡིན །',
    labelGallery: 'གོམས་གཤིས །',
    labelAudio: 'སྒྲ་གདངས ：',
    uploadAudio: 'སྒྲ་དབྱངས་དང་སྐད་ཆ་གཞན་གྱི་ཡིག་གཟུགས་གཞན་ལྟར་སྐད་ཆ་བཤད་པའི་སྒྲ་སྒྲོན་དང་། ས་ཁྲ་སྟེང་གི་མཐོང་སྣང་དང་ཟུར་གྱི་སྒྲ་སྒྲོན་བཅས་ཀྱི་སྒྲ་སྒྲོན་དེ་མུ་མཐུད་དུ་གཏོང་བཞིན་ཡོད །',
    tocAllowance: 'དངུལ་འབྲེལ་བགོ་བཀྲམ་',
    allowanceTitle: 'ཉིན་རེའི་གླ་ཆ་',
    allowanceIntro: 'DeHub ནང་གསལ་བསྒྲགས ། ཉིན་རེར་གློད་བཀྲོལ་གཏོང་། མི་ཚང་མས་ཉིན་རེར་ཡི་གེ་༡༠ དང་གློག་བརྙན་དང་བརྙན་འཕྲིན་དང་སྒྲ་གྲངས་༡ དང་འགོ་འཛུགས་ཀྱི་ཡོད ། ཉིན་གང་གི་རིང་ལ་DeHub ཀྱི་རྟགས་མཚན་ནང་དངུལ་སྤྲོད་དགོས ། — 10c ཡིག་ཆ་འཕྲིན་ཡིག་ཚང་། $ 2 a gigabyte, རྒྱུན་འགྲུལ་གྱི་ཆ་ཤས་ལ་དངུལ་སྤྲོད་དགོས །',
    allowanceIntro2: 'ཡིག་ཆ་དང་བརྡ་བརྒྱུད་ཀྱི་ཡིག་ཆ་རྣམས་སོ་སོར་དབྱེ་འབྱེད་ཡོད ། གཅིག་ལས་ཐོན་པ་དེས་གཞན་ལ་གནོད་འཚེ་མི་བྱེད་པས ། ཉིན་ཞིག་གློག་བརྙན་ལེན་པར་བེད་སྤྱོད་བྱས་ཏེ ། བཅུ་ཡི་གེ་རྣམས་རང་དབང་གིས་བསྐྱུར་བར་བྱེད་དོ ། ཁོང་གཉིས་ཀྱང་དགོང་དྲོའི་ཆུ་ཚོད་ཕྱེད་ཙམ་ལ་ཕེབས་སོ །',
    allowanceHowTitle: 'ཇི་ལྟར་ལས་ཀ་བྱེད་པ །',
    allowanceHowDesc: 'བཀའ་རྒྱ་དེ་ཧ་ཅང་གལ་ཆེན་པོ་རེད ། བཀའ་རྒྱ་དེ་དམིགས་བསལ་གྱི་ཡིན ། ཁྱོད་ཀྱིས་གསལ་བསྒྲགས ། མ་བྱས་པའི་འཕྲིན་ཡིག་གི་ཆེད་དུ་ཁྱོད་ལ་དངུལ་སྤྲོད་མི་དགོས་པ་དང་། ཁྱོད་ཀྱིས་ཡིག་ཆ་ཆེན་པོ་ཞིག་ནམ་ཡང་ཕབ་མི་དགོས་པ་དང་། དེ་ནས་ཁྱོད་ཀྱིས་དེའི་ཆེད་དུ་དངུལ་སྤྲོད་མི་ཐུབ་པ་ཤེས་པར་བྱེད་དོ །',
    allowanceStep1Title: 'ཡར་མ་འགྲོ་སྔོན་',
    allowanceStep1: 'ཁྱོད་ཀྱི་ལག་ལེན་གྱིས་གོང་ཚད་དེ་ཁྱོད་ཀྱིས་དེ་རིང་གསལ་བསྒྲགས་བྱས་པ་ལྟར་བརྟག་དཔྱད་བྱས་ཏེ ། ཁྱོད་ཀྱི་དངུལ་ཁུག་གིས་དེ་བཀབ་ཐུབ་པ་ངོས་ལེན་བྱས་པ་ཡིན ། གང་ཡང་མ་ལེན་པ་དང་གང་ཡང་མ་ལེན་བར་དུ་མ་ལེན་ནོ །',
    allowanceStep2Title: 'གསར་འགོད་གསལ་བསྒྲགས །',
    allowanceStep2: 'ཁྱོད་ཀྱི་ལས་ཀ་དེ་རང་དབང་གི་ནང་དུ་འཚོ་བཞིན་ཡོད་པ་ལྟར་འཚོ་བཞིན་ཡོད ། ཤོག་ངོས་འདི་ཡི་བཟོ་བཅོས་མཐའ་མ་འདི་ཡི་བཟོ་བཅོས་མཐའ་མ་ཡིན །',
    allowanceStep3Title: 'ཁྱོད་ཀྱིས་གླ་ཆ་སྤྲོད་དགོས །',
    allowanceStep3: 'གནས་སྤོ་གཅིག་དང་། མཚན་རྟགས་གཅིག་དང་། གནས་སྤོ་དེའི་ཆེད་དུ་མ་གཏོགས་གཞན་གང་ཡང་མེད ། དེས་གཞི་རྟེན་གང་ཞིག་དང་ཡང་ན་BNB ལྕགས་ཐག་གང་ཞིག་ལ་DeHub ཀྱི་རྟགས་མཚན་མང་པོ་ཡོད་པར་བརྟེན །',
    allowanceUnpaidTitle: 'གལ་ཏེ ། ཁྱོད་རང་འགྱེལ་བ་ཡིན་ན །',
    allowanceUnpaidDesc: 'Posted in ས་སྟོང་གསལ་བསྒྲགས ། དངུལ་ཕོགས་མ་སྤྲོད་པའི་དངུལ་ཕོགས་དེ་ཁྱོད་ཀྱི་རྩིས་ཁྲ་ལ་ཁ་ཕྱེས་ནས་ཁྱོད་ཀྱི་གླ་ཆ་མ་སྤྲོད་བར་དུ་བཀག་འགོག་བྱེད་རྒྱུ་ཡིན ། འོན་ཀྱང་དངུལ་ཕོགས་མ་སྤྲོད་བར་དུ་བཀག་འགོག་བྱེད་རྒྱུ་ཡིན ། སང་ཉིན་གྱི་དངུལ་ཕོགས་གང་འདྲ་ཞིག་ཀྱང་ཁྱོད་ལ་ཐོབ་པར་འགྱུར །',
