    allowanceCounts1: 'ཁྱེད་ཀྱི་ཉིན་རེའི་ཡིག་ཆ་རེ་རེར་ཁྱེད་ཀྱི་ཡིག་ཆ་གཅིག་པུ་བེད་སྤྱོད་བྱེད །',
    allowanceCounts3: 'ཤོག་ངོས་འདི་ཡི་མིང་ཐོ་ནི་ཤོག་ངོས་འདི་ཡི་མིང་ཐོ་དང་མཚུངས་པ་ཞིག་ཡིན །',
    allowanceCounts4: 'ཚད་གཞི་ནི་ཚད་གཞི་ལ་བརྟེན་པ་མ་ཟད ། ཚད་གཞི་ནི་ཚད་གཞི་ཆ་ཚང་ཞིག་ཏུ་མི་ཁྱབ་པ་ཡིན་ནོ ༎ གལ་ཏེ་གློག་བརྙན་200MB གྱི་གློག་བརྙན་དེ་ཁྱོད་ཀྱི་དངུལ་ཕོགས་ལས་བརྒལ་བ་ཡིན་ན ། ཁྱོད་ཀྱིས་200MB གྱི་གློག་བརྙན་དེ་སྤྲོད་དགོས །',
    allowanceCounts5: 'བསྐྱར་གསོ་བྱེད་པ ། གྲོས་འདེབས་བྱེད་པ ། ལན་འདེབས་བྱེད་པ ། གྲོས་འདེབས་བྱེད་པ ། འཕྲིན་ཡིག་གཏོང་རྒྱུ་སོགས་གང་ཡང་མ་ཡིན །',
    allowanceBadgeNote: 'བལ་ཆུའི་ཆ་ཤས་ཤིག་གིས་ཆ་ཤས་གཉིས་ཀ་གཅིག་ཏུ་སྤོས་པར་བྱེད ། དེ་ནི་སྔར་ལས་ལྷག་པའི་དངུལ་ཕོགས་དང་གོང་ཚད་ཉུང་བ་ཞིག་ཡིན ། འཕགས་པ་དེ་ནི་DeHub གྱི་རྟགས་མཚན་ཉོ་སྐབས་ཐོབ་པའི་སློབ་སྦྱོང་གི་རྟགས་མཚན་འདྲ་མཚུངས་ཡིན ། དེ་ནི་Crab གྱི་བརྒྱ་ཆ་༥ ནས་Megalodon གྱི་བརྒྱ་ཆ་༣༠ བར་ཡིན ། དེར་བརྟེན་རྟགས་མཚན་གྱི་རིན་ཐང་ལ་ལན་འདེབས་གཅིག་ཡོད ། གཅེས་པའི་སྐུ་ཞབས་ལགས ། སྐར་ཁུང་གི་ཐེག་པ་ལྟ་བུ་དང་། ཁོང་གིས་ཁྱེད་རང་ཚོ་མཐོང་སྐབས་ཁྱེད་ཚོ་སླར་ཡང་མཐོང་འདོད་དོ །',
    tokenisedTitle: 'ཚད་མེད་དང་ཚད་མེད་ཀྱི་ཁྱད་ཆོས །',
    tokenisedSubtitle: 'ERC-1155 ལོའི་ངོ་རྒོལ་གྱི་དུས་ཚོད །',
    tokenisedDesc: 'DeHub ནང་དུ་ཡོད་པའི་སྒྲོམ་གང་རུང་ཞིག་ERC-1155 NFT ཏུ་དུམ་བུར་བཟོས་ཏེ་དུམ་བུ་༡, ༠༠༠ ཙམ་དུ་དུམ་བུར་བཟོས་ཐུབ་བོ ། ། བརྙན་ལེན་བྱེད་རྒྱུ་ནི་གདམ་ཁ་ཅན་ཡིན ། བརྙན་ལེན་བྱེད་རྒྱུ་ནི་གློག་འཕྲིན་ཞིག་ནས་གློག་འཕྲིན་གཏོང་སྐབས་གློག་འཕྲིན་གཏོང་རྒྱུ་རེད ། གློག་འཕྲིན་གཏོང་རྒྱུ་ནི་གློག་འཕྲིན་གཏོང་རྒྱུ་དང་གློག་འཕྲིན་གཏོང་རྒྱུ་དང་གློག་འཕྲིན་གཏོང་རྒྱུ་སོགས་གང་ཡང་མེད ། དངུལ་བཟོ་ཚར་བའི་རྗེས་སུ ། བཟོ་སྐྲུན་པ་རྣམས་ཀྱི་རང་དབང་ཆ་ཚང་ཡོད་དེ ། དངུལ་བཟོ་ཐབས་ཀྱི་ཐབས་ལམ་གསར་པ་ཞིག་བཟོ་རྒྱུ་ཡིན་པ་དང་། དེར་རྒྱབ་སྐྱོར་བྱེད་མཁན་ཚོས་ཁོ་ཚོས་བསམ་བློ་བཏང་བའི་ནང་དོན་ལ་དངུལ་འབོར་གཏོང་ཐུབ་པ་དང ། སྐར་མའི་འབྱུང་འགྱུར་ལ་རྒྱབ་སྐྱོར་བྱེད་མཁན་གྱི་རྟགས་མཚན་གྱི་ངོ་རྒོལ་ཅན་གྱི་རྣམ་པ་ཞིག་བཟོ་རྒྱུ་ཡིན་པ་དང་།',
