    spRotationDesc: 'པིན་གྱི་ཚབ་ཏུ་པིན་གྱི་ཚབ་ཏུ་པིན་གྱི་འཁོར་ལོའོ ། ཕྱོགས་གཅིག་ཏུ་ཡར་རྒྱས་མང་པོ་བྱུང་བའི་སྐབས་ལྟ་བ་བྱེད་མཁན་རེ་རེར་གཅིག་ལ་ལྟ་བ་བྱེད་དེ ། ཕྱོགས་གཅིག་ཏུ་ཡར་རྒྱས་གོང་འཕེལ་གྱི་ཚད་གཞི་ཞིག་ཡོད་པ་ཡིན་ཏེ ། ཕྱོགས་གཅིག་ཏུ་ཡར་རྒྱས་གོང་འཕེལ་གྱི་ཚད་གཞི་ཞིག་སྟོན་པ་དང་། ཕྱོགས་གཅིག་ཏུ་ཡར་རྒྱས་གོང་འཕེལ་གྱི་ཚད་གཞི་ཞིག་ཡོད་པ་ཡིན་ཏེ ། སྒྲ་དབྱངས་ཀྱི་ཆ་ཤས་ཤིག་ཉོ་རྒྱུ་ནི་ཆུ་ཚོད་གྲངས་ཉུང་ཙམ་གྱི་རིང་ལ་ཡིན་ཞིང་། དེ་ནི་ཟས་ཀྱི་ཐོག་གི་ཆ་ཤས་ཤིག་ཡིན་པར་མ་ཟད །',
