    feedsStoriesDesc: 'སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་བཅུ་གཉིས་པ ། ཐེངས་བཅུ་པ ། ཤོག་སྒྲིལ་དེའི་སྟེང་གི་སྒྲུང་གི་སྒྲུང་གི་སྒྲུང་གི་སྒྲུང་གི་སྒྲུང་གི་སྒྲུང་གི་སྒྲུང་གི་སྒྲུང་།',
    feedsPolls: 'བཙག་འཐུ་།',
    feedsPollsDesc: 'ཚོགས་རྒྱན་བཙུགས་པའི་ཆེད་ཡིག་ཚང་ཞིག་བཟོས་ནས་དྲ་ཐོག་གི་ཚོགས་རྒྱན་བསྡུ་ལེན་བྱེད་དགོས ། གྲུབ་འབྲས་རྣམས་འཚོ་བཞིན་དུ་གསར་བཅོས་བྱས་ཏེ ། སྤྱི་ཚོགས་ཀྱི་ཐག་གཅོད་དང་སྲིད་སྐྱོང་གི་བསམ་ཚུལ་ལ་སྣེ་འཁྲིད་བྱེད་ཕྱིར་ལག་ལེན་བྱེད་ཐུབ །',
    feedsTabs: 'ཕྱོགས་སྟོན ། གཙོ་ངོས ། "རྩོམ་རིག"',
    feedsTabsDesc: 'གློག་བརྙན་དང་བརྙན་འཕྲིན་དང་གླུ་གཞས་དང་འཚོ་བཞིན་པའི་ཐིག་ཁྲམ་གཉིས་ཀྱི་བར་ལ་བསྒྱུར་ནས་རང་རང་སོ་སོའི་དབྱེ་ཚུལ་དང་འབྲེལ་བའི་དབྱེ་ཚུལ་རྣམས་རང་རང་སོ་སོའི་དབྱེ་ཚུལ་དང་འབྲེལ་བའི་དབྱེ་ཚུལ་རྣམས་རང་རང་སོ་སོའི་དབྱེ་ཚུལ་དང་འབྲེལ་བའི་དབྱེ་ཚུལ་ཞིག་ཏུ་བསྒྱུར་དགོས །',
    feedsBookmarks: 'ཡིག་རྟགས (_L) ：',
    feedsBookmarksDesc: 'ཁྱེད་ཀྱི་སྒེར་གྱི་ཤོག་ངོས་ཀྱི་མིང་རྟགས་སུ་ཡིག་ཆ་གང་འདྲ་ཞིག་བཞག་ནས་དེའི་རྗེས་སུ་འཇུག་ནས་platform leaderboard གི་སྟེང་གི་རྩོམ་པ་པོ་གཙོ་བོ་རྣམས་འཛིན་བཟུང་བྱེད་དགོས ། འདི་ཚོ་གཤམ་གསལ་ལྟར་བཀོད་ཡོད་པའི་ཨལ་གེ་རི་ཐོམ་ལྟར་བཀོད་ཡོད །',
    feedsReactions: 'ལན་སློག:',
