    aiSuiteB4Desc: 'པར་རིས་དང་། གློག་བརྙན ། སྒྲ་དབྱངས་དང་། སྒྲ་དབྱངས་དང་། 3D བཟོ་རྣམ་སོགས་ཀྱི་ཆེད་དུ་རང་ཡུལ་མི་རབས་ཀྱི་བརྙན་ཁང་ཞིག་དང་། Canva སྒྲིག་འཇུག་བྱས་ཚད ། འདྲ་མཉམ་བཟོ་སྐྲུན་ཁང་ཞིག་དང་། འདྲ་མཉམ་བཟོ་སྐྲུན་ཁང་ཞིག་དང་། འདྲ་མཉམ་བཟོ་སྐྲུན་ཁང་ཞིག་དང་། འདྲ་མཉམ་བཟོ་སྐྲུན་ཁང་ཞིག་དང་།',
    aiSuiteB5Desc: 'གནས་ཡིག་ཞིག་ཏུ་རོགས་རམ་བྱེད་པ ། བརྗོད་བྱ་ཞིག་ཏུ་རོགས་རམ་བྱེད་པ ། ཡང་ན་སྐད་ཆ་འཕྲོས་པའི་ནང་རོགས་རམ་བྱེད་པ ། དེའི་ལན་འདེབས་ནི་ཚིག་གི་མཐུན་རྐྱེན་ལས་ཚབ་ཏུ་དངོས་འབྲེལ་གྱི་གོ་རིམ་གྱི་ཡོ་བྱད་བེད་སྤྱོད་བྱེད་པ་རེད ། ཡང་ཁོ་ཚོས་མི་ཞིག་ལ་ཐུག་པའི་རྒྱབ་སྐྱོར་གྱི་ཐོ་བཀོད་ཞིག་ཀྱང་འབུལ་ཐུབ །',
