    featureBoardTitle: 'སྙན་ཞུའི་ཞུ་བ །',
    featureBoardDesc: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་10 ལས་ཉུང་བ ། ཐོན་རིམ་5.7.1 ནང་དུ་ཚོད་ལྟ་བྱས་ཟིན ། ཟླ 6 སྔོན་ལ་གསར་བཅོས་བྱས ། ལས་འགན་ཞུ་བའི་སྒྲོམ་སྟེང་བསམ་འཆར་འབུལ་བ ། མི་གཞན་གྱི་ཞུ་ཡིག་ལ་འོས་འདུ་བྱེད་པ ། དེ་དག་Shipped ལ་འགྲོ་བ་མཐོང་བ ། — ཁྱོད་ཀྱིས་ཞུ་བའི་ལས་འགན་ཞིག་འཚར་ལོངས་བྱུང་ན ། མཆོད་ཆས་དེས་ཁྱོད་ལ་ངོ་སྤྲོད་ཀྱི་བརྡ་འཕྲིན་ཞིག་སྤྲོད་དགོས །',
    connectTitle: 'AI (MCP) སྦྲེལ་མཐུད །',
    connectDesc: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་10 ལས་ཉུང་བ ། ཐོན་རིམ་5.7.1 ནང་དུ་ཚོད་ལྟ་བྱས་ཟིན ། ཟླ 6 སྔོན་ལ་གསར་བཅོས་བྱས ། ཕྱོགས་སྟོན ། གཙོ་ངོས ། "རྩོམ་རིག" dehub.io/connect',
    notificationsTitle: 'གསལ་བསྒྲགས །',
    notificationsDesc: 'ཁྱོད་ཀྱི་ཐོག་ཏུ་བྱུང་བའི་གནས་ཚུལ་ཐམས་ཅད་བརྡ་སྤྲོད་ལྟེ་བ་གཅིག་ཏུ་བགོས་ཏེ ། དེའི་ལན་འདེབས་ཀྱིས་དངུལ་སྤྲོད་མ་ཐུབ་པའི་ཕྱིར་ཡིན ། གྲོས་འདེབས་དང་ལན་འདེབས་དང་། ཁྱོད་ཀྱི་འཕྲིན་ཡིག་གི་ལན་འདེབས་དང་། རྗེས་འབྲང་པ་གསར་པ ། གྲོས་འདེབས་དང་ཉོ་ཚོང་སོགས་ཀྱི་སྐོར་གྱི་དྲན་བསྐུལ་དང་། ཁྱོད་ཀྱིས་བཀའ་བསྡུར་བྱས་པའི་དུས་ཚོད་དང་། སྤྱི་ཚོགས་ལས་འགུལ་སོགས་ཀྱི་སྐོར་གྱི་དྲན་བསྐུལ་སོགས་དང་། ཁྱོད་ཀྱིས་བཀའ་བསྡུར་བྱས་པའི་སྒྲོམ་སྟེང་གི་ཁྱད་ཆོས་ཞིག་དངོས་གནས་གྲུ་གཟིངས་ནང་དུ་ཡོད་པ་ཡིན་ན་ཉེན་བརྡ་གཏོང་དགོས །',
