    accountsDesc: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་བཅུ་གཉིས་པ ། ཐེངས་བཅུ་པ ། Google, Apple ཡང་ན་Telegram དང་མཉམ་དུ་འཛུལ་ཞུགས་བྱེད་དེ ། ཁྱོད་ཀྱི་འཕྲིན་ཡིག་གི་ཁ་བྱང་དུ་བཏང་བའི་ཡིག་རྟགས་ཞིག་དང་། ཡང་ན་SMS ཞིག་དང་། ཁྱོད་ཀྱི་ཁ་པར་ཡང་ན་ཀམ་པུ་ཊར་ཞིག་དང་། ཡང་ན་ཁྱོད་ཀྱིས་སྔར་ནས་ལག་ལེན་བྱས་པའི་དངུལ་ཁུག་ཞིག་འབྲེལ་མཐུད་བྱས་ཏེ ། མ་དངུལ་གྱི་ལམ་མ་གཏོགས་གཞན་གང་རུང་ཞིག་གིས་རྒྱབ་སྐྱོར་གྱི་ཆེད་དུ་དངུལ་ཁུག་མ་བཟོས་པ་བཟོའོ ། ཁྱོད་ཀྱིས་ལྡེ་མིག་རྣམས་བཟུང་། ང་ཚོས་ནམ་ཡང་དངུལ་ཁུག་མ་ལེན་པ་དང་། ཁྱོད་ཀྱིས་གཏེར་ཁ་དེ་རྒྱབ་སྐྱོར་བྱས་པས ། ཁྱོད་ཀྱིས་གཏེར་ཁ་དེ་མ་ཉོས་པར་གཏེར་ཁ་དེ་ལེན་ཐུབ་བོ ། ཁྱོད་ཀྱིས་དངུལ་ཁུག་དེ་ཐོག་མར་ལག་ལེན་བྱེད་སྐབས་སྲུང་སྐྱོབ་བྱེད་དགོས་པ་མ་ཟད ། ཁྱོད་ཀྱིས་དངུལ་ཁུག་དེ་ཐོག་མར་ལག་ལེན་བྱེད་སྐབས་སྲུང་སྐྱོབ་བྱེད་མི་དགོས་པ་ཡིན །',
