    accountsB5Desc: 'མི་སྡེ་ཡོངས་ནས་ཁོ་ཚོར་མཐོང་བ་དང་སྣེ་ལེན་བྱེད་ཕྱིར་ཁོ་ཚོའི་མིང་གི་ཉེ་འགྲམ་དུ་མི་གྲངས་གསར་པ་ཞིག་འཁྱེར་མཁན་ཚང་མའི་མིང་། འཐུས་མི་གསར་པ་ཚོར་ཡང་རང་འདོད་ཀྱི་ལམ་སྟོན་ལམ་སྟོན་ཞིག་གནང་ཡོད ། དེ་ནི་དུས་རྗེས་མར་Settings ནས་ཕྱིར་སྒོ་ཕྱེ་ཐུབ་པ་ཡོད །',
    accountsB6: 'པེ་སག་ཡེ །',
    accountsB6Desc: '"མུ་མཐུད་ནས་མཛུབ་རྟགས་བརྒྱབ་" གདམ་ཁ་རྐྱབས ། ཤོག་ལེབ་དེ་རྩིས་ཁྲིད ། — ཡི་མེལ་དང་ཁ་པར་ཨང་གྲངས་དང་གསང་ཚིག་མེད ། འདི་ཡང་དྲ་རྒྱ་དང་Android App ནང་ཡང་འདྲ་མཚུངས་ཀྱི་Passkey སྒྲིག་འཇུག་བྱས་ཚད །',
    accountsB7: 'ནང་འདྲེན་དང་གནས་སྤར །',
    accountsB7Desc: 'ཐོ་བཀོད་ཤོག་ལེབ་ཀྱི་ནང་། ཁྱོད་ཀྱིས་སྔར་ནས་བཟུང་ཡོད་པའི་དངུལ་ཁུག་གི་ལྡེ་མིག་རྣམས་ཕྱིར་ཚོང་བྱས་ཏེ ། སྔོན་དུ་DeHub ཀྱི་རྩིས་ཁྲ་ཞིག་ཕྱིར་འབུད་བྱས་པས ། ཐོ་བཀོད་གསར་པ་ཚོས་དེ་དག་གི་དབར་ནམ་ཡང་གདམ་ཁ་བྱེད་མི་དགོས་པ་ཡིན །',
    accountsB8: 'སྤོར་བ །',
    accountsB8Desc: 'ཁྱོད་ཀྱིས་རང་གི་རྩིས་ཁྲ་དེ་Settings ལས་ཕྱིར་འབུད་བྱེད་ཐུབ་བམ ། ཁྱེད་ཀྱི་ཡིག་གཟུགས་དང་། བརྙན་ལེན་དང་བརྡ་བརྒྱུད་རྣམས་ཕྱིར་འཐེན་བྱས་ཤིང་། དེའི་ནང་རྒྱབ་སྐྱོར་གྱི་འདྲ་བཤུས་ཀྱང་ཡོད ། དེ་བཞིན་Apple གྱི་འབྲེལ་མཐུད་ཡོད་པའི་བརྡ་དོན་རྣམས་ཕྱིར་འཐེན་བྱས་པ་ཡིན ། སྔོན་དུ་བྲིས་པའི་དངོས་པོ་གང་རུང་ཞིག་སྤྱི་ཡོངས་ཀྱི་blockchain དེར་བསྡད་ཀྱི་ཡོད །',
    uploadGallery: 'གནས་ཡིག་ཞིག་ནས་སྐུ་འདྲ་མང་པོ་ཞིག་འཁྱེར་ཐུབ་པ་ལས་གཅིག་མ་གཏོགས་མེད ། བུམ་ཐང་མེད་པའི་སྐུ་འདྲ་བཞི་ཡོད ། བུམ་ཐང་རེ་རེར་མེ་ག་ལོཌོན་དུ་སྐུ་འདྲ་ཉི་ཤུ་ཙམ་འཁྱེར་ཐུབ་པ་དང་། བུམ་ཐང་རེ་རེར་མེ་ག་ལོཌོན་དུ་སྐུ་འདྲ་རེ་རེར་མེ་ག་ལོཌོན་༤༢. ༠༦༩ ཙམ་འཁྱེར་ཐུབ་བོ ། པར་རིས་འདི་ཚོ་ཁྱེད་རང་འདོད་པའི་རིམ་པ་ནས་ཕྱིར་འབུད་བྱེད་དེ ། པར་རིས་འདི་ཚོ་བཀོད་པ ། པར་རིས་འདི་ཚོ་བཀོད་པ ། པར་རིས་འདི་ཚོ་བཀོད་པ ། པར་རིས་འདི་ཚོ་བཀོད་པ ། པར་རིས་འདི་ཚོ་བཀོད་པ །',
