    profileB2: 'ཤོག་ངོས་འདི་ཡི་བཟོ་བཅོས་མཐའ་མ་:',
    profileB2Desc: 'ལག་ལེན་ནང་ཡོད་པའི་ས་ཆ་གང་རུང་དུ་ལག་འཁྱེར་ཞིག་གནོན་ནས་ལག་འཁྱེར་དེ་ཁ་ཕྱེས་དགོས ། ལག་འཁྱེར་དེ་གང་ཡིན་པ་དང་གང་ཞིག་ཁ་ཕྱེས་དགོས །',
    profileB3: 'ཡོངས་ཁྱབ་ཚད་:',
    profileB3Desc: 'ཁྱོད་ཀྱི་སྤྱི་ཚོགས་གཞན་རྣམས་འབྲེལ་མཐུད་བྱས་ན་དྲ་རྒྱ་དེས་ཁྱོད་ཀྱི་Followers རྣམས་DeHub Followers ཚོར་རྩིས་རྒྱག་རྒྱུར་སྣེ་ལེན་བྱེད །',
