    communitiesB2Desc: 'སྤྱི་ཚོགས་སོ་སོ་ལ་དམིགས་བསལ་གྱི་ཟས་བཅུད་དང་གླེང་མོལ་ཡོད་ཅིང་། དེར་འཐུས་མི་ཚོས་སྤྱི་ཚོགས་ཀྱི་བདག་པོས་གནས་སྤར་བ ། གྲོས་བསྡུར་བྱེད་པ ། ཚོགས་རྒྱན་བཙུགས་པ ། ཕན་ཚུན་གླེང་མོལ་བྱེད་པ ། གྲོས་བསྡུར་བྱེད་པ ། གྲོས་བསྡུར་བྱེད་པ །',
    walletHubB1Desc: 'མང་གཙོའི་ལྕགས་ཐག་གི་དངུལ་ཁུག་ཞིག་ཡོད ། དེ་ཡིས་DeHub tokens མཉམ་འབྲེལ་བྱས་ཡོད ། ETH, BNB, USDT, USDC དང་། གཞན་ཡང་BASE, BNB Chain, Ethereum, Robinhood Chain དང་Arc མཉམ་འབྲེལ་བྱས་ཡོད ། ཁྱོད་ཀྱི་Solana Holdings མཉམ་འབྲེལ་བྱས་ཡོད ། དངུལ་རྩིས་རྩ་བ་རྣམས་སྦས་ནས་ཡོད ། ཁྱོད་ཀྱིས་ཁ་བྱང་ཞིག་འདྲ་བཤུས་མ་བྱེད་སྔོན་དུ་ཁ་བྱང་དེ་གང་ཡིན་ནམ་ཞེས་དྲིས་པའི་ལན་དུ ། ལེན་མཁན ། བཏང་མཁན ། ཉོ་མཁན ། ཚོང་འབྲེལ་མཁན ། ཚོང་འབྲེལ་མཁན ། ལྕགས་རི་དང་དངུལ་བཅས་པ་ཚང་མ་དངུལ་གྱི་ཐིག་ཁྲམ་གཅིག་རེད །',
    walletHubB3Desc: 'DeHub Pay གྱི་བརྒྱུད་ནས ། ཡང་ན་གཞན་གྱི་དྲ་རྒྱ་ནས་Crypto དང་$ 0.50 གྱི་བརྒྱུད་ནས །',
    walletHubB4Desc: 'DeHub ཀྱི་རྟགས་མཚན་རྣམས་— ཐོག་མར་གཞི་རྟེན་དུ་— ཕྱིར་འབུད་བྱ་དགའ་ཐོབ་པ་དང་། ཁྱོད་ཀྱི་གླ་ཆ་མར་ཕབ་པའི་རྟགས་མཚན་རྣམས་ཁ་ཕྱེས་པ་དང་། BNB གྱི་ལྕགས་ཐག་དང་གཞི་རྟེན་གྱི་བར་མཚམས་ཀྱི་རྟགས་མཚན་རྣམས་ཀྱང་ཁ་ཕྱེས་སོ །',
    walletHubB5: 'སོ་ལན །',
    walletHubB5Desc: 'Solana Wallet ནང་འཇུག་བྱས་ཚད ། ཐེངས་བཅུ་གཉིས་པ ། ཐེངས་བཅུ་པ །',
    tocExchange: 'བརྗེ་སོར་བྱེད་པ',
    exchangeTitle: 'བརྗེ་སོར་བྱེད་པ',
    exchangeDesc: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་10 ལས་ཉུང་བ ། ཐོན་རིམ་5.7.1 ནང་དུ་ཚོད་ལྟ་བྱས་ཟིན ། ཟླ 6 སྔོན་ལ་གསར་བཅོས་བྱས ། DeHub གསང་བའི་ཤོག་ངོས་འདི་ནང་ཆུ་རྫིང་རེ་རེའི་གོང་ཚད་གཅིག་དང་། འཚོ་བའི་ས་ཁྲ་ཞིག་དང་། གཞི་རྟེན་ཐོག་གི་བཀའ་རྒྱ་དེབ་ཞིག་དང་། འཕྲལ་ཁམས་ཅིག་ཁར་གྱི་ཚོང་འབྲེལ་དང་འཕྲལ་དུ་ཉོ་ཚོང་སོགས་བཀོད་ཡོད ། ཁྱོད་ཀྱི་སྒོ་ཕྱེས་ཀྱི་གནས་སྟངས་ནི་ངའི་གནས་སྟངས་ཀྱི་འོག་བཀོད་ཡོད ། ཁྱོད་ཀྱི་BNB ལྕགས་ཐག་གི་གནས་སྟངས་རྙིང་པ་དེར་མཐོང་ཐུབ་པ་ཡོད ། ཁྱོད་ཀྱིས་དེ་ཕྱིར་འབུད་བྱེད་ཐུབ་པའི་ཕྱིར་ཡིན །',
    exchangeB1: 'ཚོང་འབྲེལ་འཇམ་པོ་:',
    exchangeB1Desc: 'དངུལ་ཁུག་གི་ཚོང་འབྲེལ་ལྡེ་མིག་གིས་ཚོང་འབྲེལ་འཇམ་པོ་ཞིག་དང་། ཡང་ན་དངུལ་བརྗེ་ལེན་ཆ་ཚང་ཞིག་གནང་ཡོད ། ཚོང་འབྲེལ་འཇམ་པོ་དེས་DeHub ཀྱི་རྟགས་མཚན་རྣམས་རིམ་པ་གསུམ་དུ་བཙོང་གི་ཡོད ། དངུལ་འབོར་དང་། གོང་ཚད་དང་། ངོས་ལེན་བཅས་ཡིན ། གོང་ཚད་དེ་མ་ཐག་ཏུ་བཙོང་དགོས ། གོང་ཚད་དེ་མ་སླེབས་གོང་དུ་ཁྱོད་ཀྱི་བཀའ་རྒྱ་དེ་དེབ་ནང་དུ་བཀོད་ཡོད ། ཁྱོད་ཀྱིས་ཀྱང་ཚོང་འབྲེལ་དེ་ཚིག་ཅིག་ཏུ་བཀོད་ནས་AI གྱིས་བཀང་བར་བྱེད །',
    exchangeB2: 'ཤོག་ངོས་འདི་ཡི་བཟོ་བཅོས་མཐའ་མ་གཉིས་པ །',
    exchangeB2Desc: 'སུ་ཞིག་ཀྱང་Base, Ethereum, Robinhood Chain ཡང་ན་Solana གྱི་ཆེད་དུ་$ 100 གྱི་ཆེད་དུ་སྒོ་ཕྱེས་ཐུབ ། ཆུ་མཛོད་རེ་རེར་ཤོག་ལེབ་གཅིག་ཡོད་དེ ། ས་ཁྲ་ཞིག་དང་། བཀའ་ཤོག་དེབ་ཞིག་དང་། གློག་འཕྲོས་ཉོ་ཚོང་སོགས་ཡོད ། དེ་ནས་བཟོ་བ་དེས་རང་གི་གཟུགས་བརྙན་བཟོ་ཐུབ་བོ །',
    exchangeB3: 'ཁྱོད་ཀྱིས་འདོད་བཞིན་པའི་དངུལ་སྤྲོད་ཅིག',
    exchangeB3Desc: 'ཉོ་ཚོང་གི་བཀའ་རྒྱ་དེ་ETH, USDC ཡང་ན་USDT གྱི་སྒོ་ནས་སྤྲོད་ཐུབ ། BNB གྱི་འཛིན་སྐྱོང་པ་ཚོར་ETH གྱི་ཆེད་དུ་གཅིག་པུར་བསྒྱུར་བཅོས་ཐོབ་པར་འགྱུར །',
    tocMarkets: 'ཚོང་ཁང་།',
