    marketsDesc: 'ཚོང་ཁང་གསུམ་ནས་ཁྱོད་ཀྱིས་DeHub སྟེང་གི་དངོས་པོ་ཉོ་བ་དང་བཙོང་ཐུབ་པ་དང་། DeHub ཀྱི་རྟགས་མཚན་ནས་སྤྲོད་ཐུབ་བོ །',
    marketsB1: 'སྤྱོད་མིང་།:',
    marketsB1Desc: 'Dehub.io/usernames ནང་། དངུལ་ཀྲམ་གཏན་འབེབས་ཀྱི་རིན་གོང་དུ་ཚོང་གི་ཆེད་དུ་ལག་ལེན་འཚོལ་བ ། ཁྱོད་ཀྱིས་འདོད་པའི་ལག་ལེན་འཚོལ་བ ། ཉོ་བ ། ཁྱོད་ཀྱིས་ཉོས་པའི་མིང་རྣམས་ཁྱོད་ཀྱི་སྒྲོམ་ལ་འགྲོ་དགོས ། དེ་ལྟར་བྱས་ན་རྩིས་ཁྲ་གཅིག་ལ་ཁ་གྲངས་མང་པོ་ཡོད་པ་དང་ཁོ་ཚོས་གང་འདོད་བཞིན་གྱོན་ཐུབ ། དེ་དག་སྒྲོམ་ནས་བཙོང་བའམ་ཕྱིར་འདོན་བྱེད་པའམ ། ཡང་ན་སྒྲོམ་ནས་ཕྱིར་འདོན་བྱེད་པའམ ། མིང་གཅིག་དང་གཉིས་ཀྱང་བརྗོད་ཐུབ ། གལ་ཏེ་མིང་ཞིག་མིང་མེད་པ་ཡིན་ན་ཤོག་ངོས་དེས་མིང་དེ་ཁྱོད་ལ་བཙོང་པའི་ཚབ་ཏུ་མིང་དེ་ཁྱོད་ལ་བཙོང་པར་བྱེད་དོ །',
