    povrTitle: 'POVR: མཐོང་སྣང་དང་གོ་རིམ་གྱི་དཔང་རྟགས་',
    povrDesc1: 'ང་ཚོའི་གསལ་བསྒྲགས་འཕྲུལ་རིག་གི་ཐབས་ལམ་ནི་གཞན་གང་ཞིག་ལས་ཁྱད་པར་ཅན་ཞིག་རེད ། རྒྱུན་འཛིན་གྱི་ཚོང་ཟོག་དང་blockchain ཀྱི་ཚོང་ཟོག་གི་ནང་། ང་ཚོའི་རང་ལུས་ཀྱི་ལག་ལེན་གྱི་ནང་། དམིགས་ཡུལ་གཅིག་པུ་ཞིག་ཡོད །',
    povrDesc2: '"མཐོང་སྣང་གི་དཔང་རྟགས་" ནི་ཚད་གཞི་གཅིག་ཡིན་ཞིང་། ངོ་སྤྲོད་ལས་གཞན ། ལག་ལེན་པ་ཚོར་ཕན་ཐོགས་ཉུང་ངུ་ཞིག་བྱུང་བའམ ། ལག་ལེན་པ་ཚོར་ཕན་ཐོགས་ཉུང་ངུ་ཞིག་བྱུང་བའམ །',
    povrDesc3: 'གལ་ཏེ་ཁྱོད་ཀྱིས་དངོས་གནས་མཐོང་བ་རྣམས་ས་སྟོང་དང་སྣུམ་མ་གཏོང་བར་བརྟག་དཔྱད་བྱས་ན་ཅི་འབྱུང་မလဲ ။ ཁྱོད་ཀྱིས་དངུལ་ཁུག་རེ་རེའི་དངུལ་རྩིས་ཀྱི་རྩིས་ཁྲ་བེད་སྤྱོད་བྱས་ན་ཅི་འབྱུང་ཡོང་། ཁྱོད་ཀྱིས་དངུལ་ཁུག་རེ་རེའི་དངུལ་རྩིས་ཀྱི་རྩིས་ཁྲ་བེད་སྤྱོད་བྱས་ན་ཅི་འབྱུང་ངམ ། མ་དངུལ་ལྷག་པར་གཏོང་རྒྱུ་མ་ཟད ། མ་དངུལ་ལྷག་པར་གཏོང་རྒྱུ་མ་ཟད །',
    povrDesc5: 'ང་ཚོས་དེ་ལ་"མཐོང་སྣང་དང་གོ་གནས་ཀྱི་དཔང་རྟགས་" ཡང་ན་"POVR" ཞེས་འབོད་ཀྱི་ཡོད །',
    problemTitle: 'དཀའ་ངལ་འདི་རེད །',
