    effective: 'གྲུབ་འབྲས་:',
    effectiveDate: '2024 ལོའི་ཟླ 12 ཚེས 2 ཉིན །',
    welcomeTitle: 'LTM ནང་འཚམས་འདྲི་གནང་།',
    welcomeText: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་10 ལས་ཉུང་བ ། ཐོན་རིམ་5.7.1 ནང་དུ་ཚོད་ལྟ་བྱས་ཟིན ། ཟླ 6 སྔོན་ལ་གསར་བཅོས་བྱས །',
    ourService: 'ང་ཚོའི་ལས་འགན་',
    ourServiceText2: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་བཅུ་གཉིས་པ ། ཐེངས་བཅུ་པ ། ཐེངས་བཅུ་པ །',
    softwareDevelopers: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་10 ལས་ཉུང་བ ། ཐོན་རིམ་5.7.1 ནང་དུ་',
    softwareDevText1: 'DeHub ནི་རང་དབང་ཅན་གྱི་Dao ཞིག་རེད ། ལས་སྡེ་གང་རུང་ཞིག་གིས་ཞབས་ཏོག་དེ་བདག་དབང་བྱེད་པའམ་ལག་ལེན་བྱེད་པའམ་འཛིན་སྐྱོང་བྱེད་པའམ་མེད ། སྲིད་བྱུས་ཀྱི་གོ་རིམ་དང་གཏེར་མཛོད་ནི་DeHub གསང་བའི་འཛིན་སྐྱོང་གི་གོ་རིམ་བརྒྱུད་དེ་འཛིན་བཟུང་བྱས་ཡོད ། སྲིད་བྱུས་ཀྱི་གོ་རིམ་དེ་འཚོ་བཞིན་ཡོད ། ད་ལྟའི་གྲོས་ཆོད་ནང་"DeHub", "we", "us" དང་"us" ཞེས་པ་དེ་ནི་Dao དང་དེའི་སྲིད་སྐྱོང་གི་ཆོ་ག་ལ་མཚོན་པ་ཡིན་ཏེ ། ལས་སྡེ་ཞིག་མིན་པ་ཡིན་ནོ ༎',
