    burnMintText: 'DeHub གིས་Burn & Mint སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་བཅུ་གཉིས་པ ། ཐེངས་བཅུ་པ ། ཐེངས་བཅུ་པ ། ལས་འགན་འདི་ནི་སྤྱི་ཚོགས་སྲུང་སྐྱོབ་དང་གནས་སྟངས་ངོ་མཚར་ཅན་ཞིག་ཏུ་སྦས་པའི་སྐྱེ་ལྡན་སྐྱེ་ལྡན་གྱི་དྲང་པོ་སྲུང་སྐྱོབ་ཀྱི་ཆེད་དུ་སྲུང་སྐྱོབ་ཀྱི་ཐབས་ལམ་ཞིག་ཏུ་འགྱུར་ཡོད །',
