    permissionsText: 'ཁྱོད་ཀྱིས་ཞབས་ཏོག་དེ་ཁྱོད་ལ་ཐོབ་པའི་ཐབས་ལམ་དང་བསྟུན་ཏེ་ལག་ལེན་བྱེད་ཐུབ ། ཁྱོད་ཀྱིས་གྲོས་ཆོད་དང་ཁྲིམས་ལུགས་དང་མཐུན་པ་ཡིན་ན་དེ་ལྟར་བྱེད་དགོས །',
    notAllowed: 'ཁྱོད་ཀྱིས་འདི་ལྟར་བྱེད་མི་རུང་།',
    notAllowedItem1: 'ཞབས་ཏོག་དེ་ལག་ལེན་བྱས་ཏེ་ཁྲིམས་འགལ་གྱི་དོན་གནད་གང་ཞིག་བགོས་སྒྲིལ་བྱེད་ཆོག་པའི་དབང་ཆ་ཡོད་ན །',
    notAllowedItem2: 'ཞབས་ཏོག་གི་སྲུང་སྐྱོབ་དང་འབྲེལ་བའི་ཁྱད་ཆོས་ལ་གནོད་འཚེ་བྱེད་པ ། བཀག་དམ་བྱེད་པ ། ཡང་ན་གནོད་འཚེ་བྱེད་པ །',
    notAllowedItem3: 'ཞབས་ཏོག་ལ་སྣེ་ལེན་བྱེད་ཕྱིར་རང་བཞིན ། རང་བཞིན་གྱིས་བེད་སྤྱོད་བྱེད་པའི་ཡོ་བྱད་རྣམས་མ་གཏོགས་གསལ་པོར་ཆོག་པའི་ཡོ་བྱད་རྣམས་བེད་སྤྱོད་བྱེད་དགོས །',
