    notAllowedItem6: 'འབྲེལ་གཏོགས་ཀྱི་ཚད་གཞིའི་ལག་ལེན་སྤྲོད་པའམ་སེམས་ཤུགས་ཅན་གྱི་འབྲེལ་འདྲིས་ཀྱི་སྒོ་ནས་ལག་ལེན་བསྟར་བ །',
