    monetizationText: 'རང་ལུགས་ཀྱི་དྲ་ལམ་དང་མི་འདྲ་བའི་DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་བཅུ་གཉིས་པ ། ཐེངས་བཅུ་པ །',
    monetizationItem1: 'ཁྲིམས་དཔོན་གྱི་མངའ་སྡེ་ཁག་གི་ཁྲིམས་ལུགས་',
    monetizationItem2: 'དྭངས་གསལ་ཅན་གྱི་ཚོགས་འདུའི་སྒོ་ནས་སྲིད་སྐྱོང་གི་ཐག་གཅོད་བྱས་པ །',
