    monetizationOwnership: 'ཁྱོད་ཀྱིས་ཁྱོད་ཀྱི་དོན་ཆས་ཀྱི་བདག་དབང་ཆ་ཚང་དང་དངུལ་བཟོ་ཐབས་ཀྱི་དབང་ཆ་ཡོད་དེ ། དེ་དག་ལ་གྲོས་སྟོན་དང་། ཐོ་བཀོད་དང་། NFT ཚོང་འབྲེལ་དང་། གཞན་ཡང་blockchain གཞི་རྟེན་གྱི་འབབ་ཁུངས་ཀྱི་འབྱུང་ཁུངས་སོགས་ཡོད །',
