    decentralizedModerationItem1: 'གསང་བའི་འཛིན་བཟུང་བྱེད་མཁན་ཚོས་དོན་གནད་ཀྱི་སྲིད་བྱུས་དང་སྲུང་སྐྱོབ་ཀྱི་ལས་འགུལ་ལ་རྒྱབ་སྐྱོར་བྱེད་ཀྱི་འདུག',
    decentralizedModerationItem2: 'ཚད་འཛིན་གྱི་སྲིད་བྱུས་ཀྱི་གྲོས་ཐག་གཅོད་པའི་ཆེད་དུ་གསལ་བའི་ཚོགས་རྒྱན་གྱི་རིམ་པ་',
    designatedModerators: 'མདོ་སྨད་ཆེན །',
    designatedModeratorsText: 'སྤྱི་ཚོགས་འདེམས་བསྐོས་བྱས་པའི་འཛིན་སྐྱོང་པ་དང་གོ་གནས་མཐོ་ཤོས་ཀྱི་འཛིན་སྐྱོང་པ་ཚོར་རང་དབང་ཅན་གྱི་ཚད་འཛིན་ཐོབ་ཐང་ཡོད ། དེ་དག་གིས་དོན་གནད་དེ་དག་ཕྱིར་འདོན་བྱས་ཏེ ། ངན་ལྷད་ཅན་གྱི་རྩིས་ཁྲ་རྣམས་མྱུར་དུ་མཚམས་འཇོག་བྱེད་པའམ་ཕྱིར་འདོན་བྱེད་ཆོག་པ་ཡིན ། དེ་དག་གིས་དོན་གནད་དེ་དག་ཁྲིམས་འགལ་ཡིན་ན ། ཡང་ན་སྤྱི་ཚོགས་ཀྱི་ལམ་སྟོན་དང་འགལ་བའམ ། ཡང་ན་ལག་ལེན་པ་ཚོར་གནོད་སྐྱོན་འབྱུང་བའི་ཉེན་ཁ་ཡོད་ན ། དེ་དག་གིས་སྲིད་སྐྱོང་གི་འོས་འདུ་མ་སྒུག་པར་བྱེད་ཆོག་པ་ཡིན །',
    designatedModeratorsItem1: 'ཚད་འཛིན་པ་ཚོར་འཕྲིན་ཡིག་དང་། དཔྱད་བརྗོད་དང་། རྒྱུགས་ཆས ། ཡང་ན་བརྡ་བརྒྱུད་ཀྱི་དངོས་པོ་གང་རུང་དེ་འཕྲོ་ལས་ཕྱིར་འདོན་བྱེད་ཆོག་པ་ཡིན །',
