    designatedModeratorsItem4: 'སྲིད་སྐྱོང་གིས་སྲིད་བྱུས་དེ་གཏན་འབེབས་བྱས་ཤིང་། སྲིད་སྐྱོང་པ་ཚོས་རང་གི་ཐག་གཅོད་རྣམས་བསྐྱར་ཞིབ་བྱེད་པའམ་བསྒྱུར་བཅོས་བྱེད་སྲིད་མོད ། འོན་ཀྱང་དེ་མ་ཐག་ཏུ་རང་ལུས་ཀྱི་སྲུང་སྐྱོབ་དེ་ངེས་པར་དུ་བྱེད་དགོས་པ་ཡིན །',
