    rightsYouGrant: 'ཁྱོད་ཀྱིས་ཐོབ་པའི་ཐོབ་ཐང་',
    rightsYouGrantText: 'ཁྱོད་ཀྱི་ནང་དོན་ནང་ཡོད་པའི་དབང་ཆ་ཚང་མ་ཁྱོད་ལ་ཐོབ་པར་འགྱུར ། ཁྱོད་དང་འབྲེལ་བ་ཡོད་པའི་དངོས་པོ་རྣམས་ཁྱོད་དང་འབྲེལ་བ་ཡོད་པའི་དངོས་པོ་ཡིན །',
