    a6: 'ཡིན་ནམ ། ཁྱོད་ཀྱིས་DeHub ཀྱི་རྟགས་མཚན་ལ་ཞུགས་ཐུབ་པ་ཡོད ། ཁྱོད་ཀྱིས་དངོས་འབྲེལ་གྱི་ཐོན་སྐྱེད་ཐོབ་ཐུབ་པ་ཡོད ། ཁྱོད་ཀྱིས་X-2 གྱི་བྱ་དགའ་ཐོབ་ཐུབ་པ་ཡོད ། རྒྱུན་སྐྱོང་བྱེད་རྒྱུ་དེའང་དྲ་རྒྱ་སྲུང་སྐྱོབ་བྱེད་དུ་འཇུག་པ་དང་། རང་བཞིན་གནས་སྟངས་ཀྱི་ནང་འཁོད་ལུ་ཐོབ་ཐང་ཡར་རྒྱས་སུ་གཏོང་རྒྱུར་རོགས་བྱེད་དོ །',
