    a10: 'DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་10 ལས་ཉུང་བ ། ཐོན་རིམ་5.7.1 ནང་དུ་ཚོད་ལྟ་བྱས་ཟིན ། ཟླ 6 སྔོན་ལ་གསར་བཅོས་བྱས ། འབྲེལ་ཡོད་གསལ་བསྒྲགས་སྟོན་ཆེད་རྩོམ་པ་པོ་ཚོས་བྱ་དགའ་ཐོབ་ཐུབ །',
