    a11: 'ལགས་སོ ། DeHub སྒྲིག་འཇུག་བྱས་ཚད ། ཐེངས་བཅུ་གཉིས་པ ། ཐེངས་བཅུ་པ ། ང་ཚོས་ང་ཚོའི་གློག་རིག་གི་འཆམ་ཡིག་དང་མཐུན་རྐྱེན་ཚང་མའི་སྲུང་སྐྱོབ་ལ་ཐོག་མར་དམིགས་གཏད་བྱེད་ཀྱི་ཡོད །',
    q12: 'DeHub ཐོ་བཀོད་ཚད་ནི་ཅི་ཞིག་རེད་དམ །',
