    q14: 'DeHub token ལག་ལེན་འཐབ་པའི་ཕན་ཐོགས་ཅི་ཡོད་དམ །',
    a14: 'ཁེ་ཕན་གྱི་ཆ་ཤས་ཤིག་ནི་ཁྱད་ཆོས་ཡར་རྒྱས་ཅན་གྱི་གོ་སྐབས་དང་། འཛམ་གླིང་གི་ཚོང་འབྲེལ་དང་། བཟོ་སྐྲུན་པ་ཉོ་ཚོང་། NFT ཚོང་ཉོ་ཚོང་། གཞུང་སྐྱོང་ཐོབ་ཐང་། སྐུལ་བསྒྲགས་བྱ་དགའ་། འབྲེལ་བ་ཡོད་པའི་དྲ་རྒྱ་སྲུང་སྐྱོབ་དང་། མ་འོངས་པའི་ཕན་ནུས་ཀྱི་རྒྱ་སྐྱེད་བཅས་ཡིན །',
