    a15: 'ལགས་སོ ། ཁྱོད་ཀྱིས་DeHub ཀྱི་རྟགས་མཚན་ལག་ལེན་ཐོག་གསལ་བསྒྲགས ། ཡང་ན་སྦས་པའི་དོན་ཆས་ཀྱི་ནང་དོན་མང་པོ་བསྡུས་ནས་བཟོ་བ་དང་མཐོང་བ་ཚོར་བྱ་དགའ་སྤྲོད་ཐུབ་བོ །',
