    a17: 'ཁྱོད་ཀྱིས་DeHub གི་D \'Apps རྣམས་ང་ཚོའི་དྲ་ལམ་གཙོ་བོ་བརྒྱུད་དེ་ཐོབ་ཐུབ ། DeHub token holders ཚོས་ད་ལྟ་དང་མ་འོངས་པའི་d\' Apps ཚང་མར་ཁྱད་ཆོས་དང་ལས་འགན་ཡར་རྒྱས་ཐོབ་ཡོད །',
