    q19: 'ངས་DeHub གྱི་སྡེ་ཚན་ལ་ཇི་ལྟར་འབྲེལ་བ་བྱེད་ཐུབ་བམ །',
    a19: 'ཁྱེད་ཚོས་ང་ཚོའི་གཞུང་འབྲེལ་ལམ་བརྒྱུད་དེ་ང་ཚོར་འབྲེལ་བ་བྱེད་ཐུབ ། tech@dehub.net ཆེད་ལས་ཀྱི་གནད་དོན་ཆེད་། ཡང་ན་Twitter དང་Instagram @ dehub_གཞུང་འབྲེལ་གསར་བཅོས་དང་སྤྱི་ཚོགས་མཉམ་འབྲེལ་ཆེད་ངེད་རྣམས་རྗེས་སུ་འབྲངས་ཐུབ །',
