    a20: 'མིན ། DeHub ཀྱི་རྟགས་མཚན་ནི་DeHub ཀྱི་སྐྱེ་ལྡན་སྐྱེ་ལྡན་གྱི་ནང་དོན་གྱི་ཆེད་དུ་དམ་པོར་ཡིན ། དེ་དག་ནི་ཚོང་འབྲེལ་གྱི་ཡོ་བྱད་མིན་པ་དང་། ཚད་གཞི་ཧ་ཅང་ཡག་པོ་ཡོད །',
