    step2Title: 'རང་གི་དྲ་རྒྱ་འཚོལ་བ །',
    step3Title: 'ཁྱེད་ཀྱི་ཐོག་མའི་པར་གཞི་དེ',
    step3Desc: 'ཡིག་ཆ་ཞིག་འབྲི་བ ། པར་རིས་ཞིག་སྣོན་པ ། བརྙན་ཟློས ། སྒྲ་ཞིག་སྣོན་པ ། ཡིག་ཆ་ཞིག་ཏུ་འགྱུར་བ ། ཡིག་ཆ་ཞིག་ཏུ་འགྱུར་བ ། ཡང་ན་འཚར་ལོངས་བྱེད་པ ། ཉིན་རེའི་དངུལ་ཕོགས་ཀྱི་ཆེད་དུ་གློག་འཕྲིན་གཏོང་རྒྱུ་ནི་གློད་བཀྲོལ་ཡིན ། ཉིན་རེའི་ཡི་གེ་བཅུ་དང་བརྡ་བརྒྱུད་ཀྱི་གྷི་གབ་ཊི་གཅིག་ལ་གློག་འཕྲིན་གཏོང་རྒྱུ་ནི་གློད་བཀྲོལ་མེད་པ་ཞིག་ཡིན ། ལྕགས་ཐག་གི་སྟེང་གི་ས་ཆ་ཞིག་འཛིན་བཟུང་བྱ་རྒྱུ་དེ་གདམ་ཁ་ཅན་ཞིག་ཡིན་ཞིང་། རྗེས་སུ་ཡང་དེ་ལྟར་བྱ་ཐུབ །',
    step4Title: 'ཁྱོད་ཀྱི་སྙན་ངག་པ་ལ་གུས་ཞབས་ཞུ་བ །',
    step4Desc: 'ལས་འགན་ཚང་མ་DeHub ཀྱི་རྟགས་སུ་བཀོད་ཐུབ་བོ ། དེར་ནས་ཁྱོད་ཀྱིས་གླ་ཆ་བཙོང་ཐུབ་པ་དང་། ཤོག་ངོས་རེ་ནས་གླ་ཆ་སྤྲོད་ཐུབ་པ་དང་། འཕྲིན་ཡིག་ཐད་ཀར་ཉུང་མཐར་གཏོང་ཐུབ་པ་དང་། ཚོང་ཁང་ཞིག་ཕྱེ་ཐུབ་པ་དང་། ཤོག་ངོས་མང་པོ་བཏང་ཐུབ་པ་དང་། ཤོག་ངོས་མང་པོ་བཏང་ཐུབ་པ་དང་། ཤོག་ངོས་མང་པོ་བཏང་ཐུབ་བོ །',
    step5Title: 'སྟོད་ཐུང་ཞིག་གི་ཆེད་དུ་རྟགས་མཚན་བཟུང་།',
    step5Desc: 'DeHub རྟགས་མཚན་བཟུང་བའམ་རྡོག་བརྫིས་གཏོང་རྒྱུ་ནི་Crab ནས་Megalodon བར་གྱི་རྟགས་མཚན་ཞིག་ཡིན ། བད་གེ་ཞིག་གིས་ཁྱོད་ཀྱི་གླ་ཆ་མར་ཕབ་པ་དང་། ཁྱོད་ཀྱི་དངུལ་ཕོགས་ཡར་སེང་གཏོང་བ་དང་། SuperPowers འཕྱེས་པ་དང་། ཁྱོད་ཀྱི་བསམ་ཚུལ་དང་། ལན་འདེབས་དང་སྐད་ཆ་ལ་ཤུགས་སྣོན་གཏོང་བ་དང་།',
    step6Title: 'ཁྱོད་ཀྱི་ཁུག་པ་འཁྱེར་ཞིག',
